// RoboForge Project 1: LED Blink & Timing Lab
// Demonstrates digital output and non-blocking timing principles

const int LED_PIN = 13;

void setup() {
  // Configure digital pin 13 as a low-impedance voltage output
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  // Apply 5V to the pin: current flows through resistor and LED to GND
  digitalWrite(LED_PIN, HIGH);
  delay(1000); // Wait 1000 milliseconds (1 second)

  // Apply 0V to the pin: current stops flowing
  digitalWrite(LED_PIN, LOW);
  delay(1000); // Wait 1000 milliseconds (1 second)
}

// RoboForge Project 2: Pedestrian Crossing & Traffic Light
// Finite State Machine with Non-Blocking Pushbutton Request

const int PIN_RED = 12;
const int PIN_YELLOW = 11;
const int PIN_GREEN = 10;
const int PIN_BUTTON = 2;

enum TrafficState {
  STATE_GREEN,
  STATE_YELLOW,
  STATE_RED_PEDESTRIAN
};

TrafficState currentState = STATE_GREEN;
bool pedestrianRequested = false;
unsigned long stateStartTime = 0;

void setLights(bool r, bool y, bool g) {
  digitalWrite(PIN_RED, r ? HIGH : LOW);
  digitalWrite(PIN_YELLOW, y ? HIGH : LOW);
  digitalWrite(PIN_GREEN, g ? HIGH : LOW);
}

void setup() {
  pinMode(PIN_RED, OUTPUT);
  pinMode(PIN_YELLOW, OUTPUT);
  pinMode(PIN_GREEN, OUTPUT);

  // Enable internal 20k pull-up resistor: reads HIGH when open, LOW when pressed
  pinMode(PIN_BUTTON, INPUT_PULLUP);

  setLights(false, false, true); // Start with Green
  stateStartTime = millis();
}

void loop() {
  // Check for pedestrian request button press (active LOW)
  if (digitalRead(PIN_BUTTON) == LOW) {
    pedestrianRequested = true;
  }

  unsigned long currentDuration = millis() - stateStartTime;

  switch (currentState) {
    case STATE_GREEN:
      // Stay green for at least 5 seconds before honoring pedestrian request
      if (pedestrianRequested && currentDuration >= 5000) {
        currentState = STATE_YELLOW;
        setLights(false, true, false);
        stateStartTime = millis();
      }
      break;

    case STATE_YELLOW:
      // Yellow caution light for 2 seconds
      if (currentDuration >= 2000) {
        currentState = STATE_RED_PEDESTRIAN;
        setLights(true, false, false);
        stateStartTime = millis();
      }
      break;

    case STATE_RED_PEDESTRIAN:
      // Red stop light for vehicles (safe pedestrian crossing) for 5 seconds
      if (currentDuration >= 5000) {
        currentState = STATE_GREEN;
        setLights(false, false, true);
        pedestrianRequested = false;
        stateStartTime = millis();
      }
      break;
  }
}

// RoboForge Project 3: Autonomous Dual-Sensor Line-Following Robot
// Two-sensor Bang-Bang / Differential Steer Algorithm

// Left Motor Pins (L298N IN1, IN2)
const int L_FWD = 5;
const int L_REV = 6;

// Right Motor Pins (L298N IN3, IN4)
const int R_FWD = 9;
const int R_REV = 10;

// Line Sensor Pins
const int SENSOR_LEFT = 2;
const int SENSOR_RIGHT = 3;

// Base speed (0-255 PWM duty cycle)
const int SPEED_FWD = 160;
const int SPEED_TURN = 140;

void setLeftMotor(int speed) {
  if (speed >= 0) {
    analogWrite(L_FWD, speed);
    analogWrite(L_REV, 0);
  } else {
    analogWrite(L_FWD, 0);
    analogWrite(L_REV, -speed);
  }
}

void setRightMotor(int speed) {
  if (speed >= 0) {
    analogWrite(R_FWD, speed);
    analogWrite(R_REV, 0);
  } else {
    analogWrite(R_FWD, 0);
    analogWrite(R_REV, -speed);
  }
}

void setup() {
  pinMode(L_FWD, OUTPUT);
  pinMode(L_REV, OUTPUT);
  pinMode(R_FWD, OUTPUT);
  pinMode(R_REV, OUTPUT);

  pinMode(SENSOR_LEFT, INPUT);
  pinMode(SENSOR_RIGHT, INPUT);
}

void loop() {
  // TCRT5000: HIGH = Black line detected, LOW = White floor
  int leftDetect = digitalRead(SENSOR_LEFT);
  int rightDetect = digitalRead(SENSOR_RIGHT);

  if (leftDetect == LOW && rightDetect == LOW) {
    // Line is centered between the two sensors: DRIVE FORWARD
    setLeftMotor(SPEED_FWD);
    setRightMotor(SPEED_FWD);
  } 
  else if (leftDetect == HIGH && rightDetect == LOW) {
    // Robot is veering right: TURN SHARP LEFT
    setLeftMotor(0);
    setRightMotor(SPEED_TURN);
  } 
  else if (leftDetect == LOW && rightDetect == HIGH) {
    // Robot is veering left: TURN SHARP RIGHT
    setLeftMotor(SPEED_TURN);
    setRightMotor(0);
  } 
  else {
    // Both detected black (intersection or T-junction): STOP or crawl
    setLeftMotor(SPEED_FWD / 2);
    setRightMotor(SPEED_FWD / 2);
  }
}

// RoboForge Project 4: Obstacle-Avoiding Ultrasonic Smart Car
// Look-Ahead Sonar Scanning with Decision Tree Navigation

#include <Servo.h>

// Sonar Pins
const int PIN_TRIG = 7;
const int PIN_ECHO = 8;

// Servo Pin
const int PIN_SERVO = 11;
Servo headServo;

// Motor Driver Pins (L298N)
const int L_FWD = 5;
const int L_REV = 6;
const int R_FWD = 9;
const int R_REV = 10;

const int SAFE_DISTANCE_CM = 25; // Obstacle trigger threshold

long measureDistanceCM() {
  digitalWrite(PIN_TRIG, LOW);
  delayMicroseconds(2);
  digitalWrite(PIN_TRIG, HIGH);
  delayMicroseconds(10);
  digitalWrite(PIN_TRIG, LOW);

  // Read echo pulse duration in microseconds (timeout 25ms = ~4 meters)
  long duration = pulseIn(PIN_ECHO, HIGH, 25000);
  if (duration == 0) return 300; // No echo received, clear open space

  return duration / 58.2; // Speed of sound conversion: 343 m/s
}

void setMotors(int leftSpeed, int rightSpeed) {
  if (leftSpeed >= 0) {
    analogWrite(L_FWD, leftSpeed);
    analogWrite(L_REV, 0);
  } else {
    analogWrite(L_FWD, 0);
    analogWrite(L_REV, -leftSpeed);
  }

  if (rightSpeed >= 0) {
    analogWrite(R_FWD, rightSpeed);
    analogWrite(R_REV, 0);
  } else {
    analogWrite(R_FWD, 0);
    analogWrite(R_REV, -rightSpeed);
  }
}

void setup() {
  pinMode(PIN_TRIG, OUTPUT);
  pinMode(PIN_ECHO, INPUT);

  pinMode(L_FWD, OUTPUT);
  pinMode(L_REV, OUTPUT);
  pinMode(R_FWD, OUTPUT);
  pinMode(R_REV, OUTPUT);

  headServo.attach(PIN_SERVO);
  headServo.write(90); // Center forward
  delay(500);
}

void loop() {
  headServo.write(90); // Look straight ahead
  long frontDist = measureDistanceCM();

  if (frontDist > SAFE_DISTANCE_CM) {
    // Path is clear: DRIVE FORWARD
    setMotors(170, 170);
    delay(60);
  } else {
    // Obstacle detected! STOP immediately
    setMotors(0, 0);
    delay(200);

    // Reverse slightly to create turning clearance
    setMotors(-150, -150);
    delay(250);
    setMotors(0, 0);

    // Scan Left
    headServo.write(160);
    delay(350);
    long leftDist = measureDistanceCM();

    // Scan Right
    headServo.write(20);
    delay(400);
    long rightDist = measureDistanceCM();

    // Return head to center
    headServo.write(90);
    delay(200);

    // Decide direction: choose side with greater clearance
    if (leftDist > rightDist && leftDist > SAFE_DISTANCE_CM) {
      // Turn Left
      setMotors(-160, 160);
      delay(350);
    } else if (rightDist >= leftDist && rightDist > SAFE_DISTANCE_CM) {
      // Turn Right
      setMotors(160, -160);
      delay(350);
    } else {
      // Dead end on both sides: 180-degree spin around
      setMotors(170, -170);
      delay(650);
    }
    setMotors(0, 0);
  }
}

// RoboForge Project 5: Articulated 2-DOF Robotic Arm
// Teleoperation with Exponential Moving Average (EMA) Jitter Filter

#include <Servo.h>

const int PIN_POT_BASE = A0;
const int PIN_POT_SHOULDER = A1;

const int PIN_SERVO_BASE = 9;
const int PIN_SERVO_SHOULDER = 10;

Servo servoBase;
Servo servoShoulder;

// Filtered angle states (floating point for precision)
float filteredBase = 90.0;
float filteredShoulder = 90.0;

// Smoothing coefficient: 0.1 = very smooth/gradual, 0.5 = fast response
const float ALPHA = 0.15;

void setup() {
  servoBase.attach(PIN_SERVO_BASE);
  servoShoulder.attach(PIN_SERVO_SHOULDER);

  servoBase.write(90);
  servoShoulder.write(90);
  delay(500);
}

void loop() {
  // Read 10-bit raw ADC (0 - 1023)
  int rawBase = analogRead(PIN_POT_BASE);
  int rawShoulder = analogRead(PIN_POT_SHOULDER);

  // Map ADC range to physical servo travel limits (0 to 180 degrees)
  float targetBase = map(rawBase, 0, 1023, 10, 170);
  float targetShoulder = map(rawShoulder, 0, 1023, 20, 160);

  // Apply Exponential Moving Average filter: Y[n] = (1 - alpha)*Y[n-1] + alpha*X[n]
  filteredBase = (1.0 - ALPHA) * filteredBase + ALPHA * targetBase;
  filteredShoulder = (1.0 - ALPHA) * filteredShoulder + ALPHA * targetShoulder;

  // Command servos with filtered integer angles
  servoBase.write((int)filteredBase);
  servoShoulder.write((int)filteredShoulder);

  // Short delay for 50Hz control loop pacing
  delay(20);
}
